function lasery_xtool_default_privacy_html($language) {
    $text = lasery_xtool_privacy_texts($language);
    $html = '';
    foreach (['controller', 'purposes', 'storage', 'recipients', 'rights', 'cookies'] as $section) {
        $body = str_replace('Michal@laseryxtool.pl', lasery_xtool_contact_email(), $text[$section . '_text']);
        $html .= '<section><h2>' . esc_html($text[$section]) . '</h2><p>' . esc_html($body) . '</p></section>';
    }
    return $html . '<p><a href="https://www.xtool.eu/policies/privacy-policy" rel="noopener noreferrer">' . esc_html($text['external']) . '</a></p>';
}
